function makeId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function stamp() {
  return new Date().toISOString();
}

function clean(value, fallback = "", limit = 1600) {
  if (typeof value !== "string") return fallback;
  const result = value.trim();
  return result ? result.slice(0, limit) : fallback;
}

function blankData() {
  return { incidents: [], actions: [], timeline: [], impacts: [], communications: [], evidence: [], owners: [] };
}

function readData() {
  if (typeof window === "undefined") return blankData();
  try {
    return { ...blankData(), ...JSON.parse(window.localStorage.getItem(STORAGE_KEY) || "{}") };
  } catch {
    return blankData();
  }
}

function tone(value) {
  if (["resolved", "closed", "done", "contained", "monitoring"].includes(value)) return "emerald";
  if (["critical", "high", "blocked", "detected"].includes(value)) return "rose";
  if (["medium", "triage", "in-progress"].includes(value)) return "amber";
  return "slate";
}

function Button({ children, icon: Icon, onClick, variant = "secondary", type = "button" }) {
  const variants = {
    secondary: "border-slate-200 bg-white text-slate-700 hover:border-slate-300",
    primary: "border-orange-600 bg-orange-600 text-white hover:bg-orange-700",
    danger: "border-rose-200 bg-white text-rose-700 hover:bg-rose-50",
    quiet: "border-transparent bg-slate-50 text-slate-600 hover:bg-slate-100",
  };
  return <button type={type} onClick={onClick} className={`inline-flex h-9 items-center justify-center gap-2 rounded-lg border px-3 text-xs font-semibold ${variants[variant]}`}>{Icon && <Icon size={14} />}{children}</button>;
}

function Badge({ children, value }) {
  const colors = {
    slate: "border-slate-200 bg-slate-50 text-slate-700",
    emerald: "border-emerald-200 bg-emerald-50 text-emerald-800",
    amber: "border-amber-200 bg-amber-50 text-amber-800",
    rose: "border-rose-200 bg-rose-50 text-rose-800",
  };
  return <span className={`inline-flex rounded-full border px-2.5 py-1 text-[11px] font-semibold ${colors[tone(value)] || colors.slate}`}>{children}</span>;
}

function Field({ label, value, onChange, placeholder, options, required = false }) {
  const common = { value: value || "", onChange: (event) => onChange(event.target.value), required, className: "mt-1.5 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm outline-none focus:border-orange-500" };
  return <label className="block text-xs font-semibold text-slate-700">{label}{options ? <select {...common}><option value="">Select...</option>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select> : <input {...common} placeholder={placeholder} />}</label>;
}

function Area({ label, value, onChange, placeholder }) {
  return <label className="block text-xs font-semibold text-slate-700">{label}<textarea value={value || ""} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} rows={4} className="mt-1.5 w-full resize-y rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-orange-500" /></label>;
}

function Empty({ title, description, action }) {
  return <div className="p-8 text-center"><p className="text-sm font-semibold text-slate-800">{title}</p><p className="mx-auto mt-1 max-w-md text-xs text-slate-500">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}

function Section({ title, description, action, children }) {
  return <section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-start justify-between gap-3 border-b border-slate-100 p-5"><div><h3 className="text-sm font-semibold text-slate-950">{title}</h3><p className="mt-1 text-xs text-slate-500">{description}</p></div>{action}</div>{children}</section>;
}

function Modal({ title, onClose, children }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b p-5"><h2 className="font-semibold">{title}</h2><button type="button" onClick={onClose}><X size={17} /></button></div><div className="p-5">{children}</div></div></div>;
}

function Stat({ icon: Icon, label, value, detail }) {
  return <article className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-3xl font-semibold">{value}</p></div><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-orange-100 text-orange-700"><Icon size={17} /></span></div><p className="mt-2 text-[11px] text-slate-500">{detail}</p></article>;
}

export default function TesterIncidentResponseWorkspace({ reports = [], onOpenReport }) {
  const [data, setData] = useState(blankData);
  const [selectedId, setSelectedId] = useState("");
  const [tab, setTab] = useState("overview");
  const [query, setQuery] = useState("");
  const [ascending, setAscending] = useState(false);
  const [modal, setModal] = useState("");
  const [notice, setNotice] = useState("");
  const [incidentForm, setIncidentForm] = useState({ title: "", severity: "medium", state: "detected", lead: "", service: "", summary: "" });
  const [actionForm, setActionForm] = useState({ title: "", state: "planned", owner: "", priority: "medium", due: "", detail: "" });
  const [timelineForm, setTimelineForm] = useState({ title: "", type: "Observation", author: "", detail: "", time: "" });
  const [impactForm, setImpactForm] = useState({ area: "Users", severity: "medium", count: "", detail: "", confidence: "medium" });
  const [communicationForm, setCommunicationForm] = useState({ channel: "Status page", audience: "", author: "", message: "", status: "draft" });
  const [evidenceForm, setEvidenceForm] = useState({ title: "", kind: "Screenshot", reference: "", detail: "" });
  const [ownerForm, setOwnerForm] = useState({ name: "", role: "", area: "", availability: "available", backup: "" });

  useEffect(() => setData(readData()), []);
  useEffect(() => { if (typeof window !== "undefined") window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => { if (!notice) return undefined; const timer = window.setTimeout(() => setNotice(""), 2600); return () => window.clearTimeout(timer); }, [notice]);

  const incident = data.incidents.find((item) => item.id === selectedId);
  const actions = data.actions.filter((item) => !selectedId || item.incidentId === selectedId);
  const timeline = data.timeline.filter((item) => !selectedId || item.incidentId === selectedId);
  const impacts = data.impacts.filter((item) => !selectedId || item.incidentId === selectedId);
  const communications = data.communications.filter((item) => !selectedId || item.incidentId === selectedId);
  const evidence = data.evidence.filter((item) => !selectedId || item.incidentId === selectedId);
  const owners = data.owners.filter((item) => !selectedId || item.incidentId === selectedId);
  const activeActions = actions.filter((item) => !["done", "cancelled"].includes(item.state));
  const criticalImpacts = impacts.filter((item) => ["critical", "high"].includes(item.severity));
  const doneActions = actions.filter((item) => item.state === "done").length;
  const actionScore = actions.length ? Math.round((doneActions / actions.length) * 100) : 0;
  const filteredTimeline = useMemo(() => timeline.filter((item) => `${item.title} ${item.type} ${item.author} ${item.detail}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => { const result = String(a.time || a.createdAt).localeCompare(String(b.time || b.createdAt)); return ascending ? result : result * -1; }), [ascending, query, timeline]);

  function update(key, items) { setData((current) => ({ ...current, [key]: items })); }
  function addIncident(event) { event.preventDefault(); const item = { ...incidentForm, id: makeId("incident"), title: clean(incidentForm.title), lead: clean(incidentForm.lead), service: clean(incidentForm.service), summary: clean(incidentForm.summary), createdAt: stamp() }; update("incidents", [item, ...data.incidents]); setSelectedId(item.id); setIncidentForm({ title: "", severity: "medium", state: "detected", lead: "", service: "", summary: "" }); setModal(""); setNotice("Incident created"); }
  function addAction(event) { event.preventDefault(); const item = { ...actionForm, id: makeId("action"), incidentId: selectedId, title: clean(actionForm.title), owner: clean(actionForm.owner), due: clean(actionForm.due), detail: clean(actionForm.detail), createdAt: stamp() }; update("actions", [item, ...data.actions]); setActionForm({ title: "", state: "planned", owner: "", priority: "medium", due: "", detail: "" }); setModal(""); setNotice("Response action added"); }
  function addTimeline(event) { event.preventDefault(); const item = { ...timelineForm, id: makeId("timeline"), incidentId: selectedId, title: clean(timelineForm.title), author: clean(timelineForm.author), detail: clean(timelineForm.detail), time: clean(timelineForm.time) || stamp(), createdAt: stamp() }; update("timeline", [item, ...data.timeline]); setTimelineForm({ title: "", type: "Observation", author: "", detail: "", time: "" }); setModal(""); setNotice("Timeline event added"); }
  function addImpact(event) { event.preventDefault(); const item = { ...impactForm, id: makeId("impact"), incidentId: selectedId, count: clean(impactForm.count), detail: clean(impactForm.detail), createdAt: stamp() }; update("impacts", [item, ...data.impacts]); setImpactForm({ area: "Users", severity: "medium", count: "", detail: "", confidence: "medium" }); setModal(""); setNotice("Impact assessment added"); }
  function addCommunication(event) { event.preventDefault(); const item = { ...communicationForm, id: makeId("communication"), incidentId: selectedId, audience: clean(communicationForm.audience), author: clean(communicationForm.author), message: clean(communicationForm.message), createdAt: stamp() }; update("communications", [item, ...data.communications]); setCommunicationForm({ channel: "Status page", audience: "", author: "", message: "", status: "draft" }); setModal(""); setNotice("Communication update added"); }
  function addEvidence(event) { event.preventDefault(); const item = { ...evidenceForm, id: makeId("evidence"), incidentId: selectedId, title: clean(evidenceForm.title), reference: clean(evidenceForm.reference), detail: clean(evidenceForm.detail), createdAt: stamp() }; update("evidence", [item, ...data.evidence]); setEvidenceForm({ title: "", kind: "Screenshot", reference: "", detail: "" }); setModal(""); setNotice("Incident evidence added"); }
  function addOwner(event) { event.preventDefault(); const item = { ...ownerForm, id: makeId("owner"), incidentId: selectedId, name: clean(ownerForm.name), role: clean(ownerForm.role), area: clean(ownerForm.area), backup: clean(ownerForm.backup), createdAt: stamp() }; update("owners", [item, ...data.owners]); setOwnerForm({ name: "", role: "", area: "", availability: "available", backup: "" }); setModal(""); setNotice("Response owner added"); }
  function change(key, itemId, field, value) { update(key, data[key].map((item) => item.id === itemId ? { ...item, [field]: value, updatedAt: stamp() } : item)); }
  function remove(key, itemId) { update(key, data[key].filter((item) => item.id !== itemId)); setNotice("Record removed"); }
  function applyChecklist() { if (!selectedId) { setNotice("Select an incident first"); return; } const items = RESPONSE_CHECKLIST.map(([title, phase, owner], index) => ({ id: makeId(`response-${index}`), incidentId: selectedId, title, phase, state: "planned", owner, priority: "medium", detail: "", due: "", createdAt: stamp() })); update("actions", [...items, ...data.actions]); setNotice("Response checklist applied"); }
  function copySummary() { navigator.clipboard?.writeText([`Incident: ${incident?.title || "All incidents"}`, `State: ${incident?.state || "Not selected"}`, `Severity: ${incident?.severity || "Not selected"}`, `Action completion: ${actionScore}%`, `Active actions: ${activeActions.length}`, `Critical impacts: ${criticalImpacts.length}`, `Timeline events: ${timeline.length}`, `Evidence: ${evidence.length}`, incident?.summary || "No summary recorded."].join("\n")); setNotice("Incident summary copied"); }
  function exportData() { const rows = [["Type", "Title", "State", "Owner", "Detail"], ...actions.map((item) => ["Action", item.title, item.state, item.owner, item.detail]), ...timeline.map((item) => ["Timeline", item.title, item.type, item.author, item.detail]), ...impacts.map((item) => ["Impact", item.area, item.severity, item.count, item.detail])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell || "").replaceAll('"', '""')}"`).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "tester-incident-response.csv"; anchor.click(); URL.revokeObjectURL(url); setNotice("Incident data exported"); }

  const tabs = [["overview", "Overview"], ["actions", `Actions (${actions.length})`], ["timeline", `Timeline (${timeline.length})`], ["impact", `Impact (${impacts.length})`], ["communications", `Updates (${communications.length})`], ["evidence", `Evidence (${evidence.length})`], ["owners", `Owners (${owners.length})`]];
  return <section className="mt-8 space-y-5">
    <div className="rounded-3xl border border-orange-200 bg-gradient-to-br from-orange-50 via-white to-rose-50 p-5 shadow-sm sm:p-7"><div className="flex flex-col gap-5 lg:flex-row lg:justify-between"><div className="max-w-3xl"><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.16em] text-orange-700"><Siren size={16} /> Incident response workspace</div><h2 className="mt-3 text-2xl font-semibold tracking-tight text-slate-950 sm:text-3xl">Coordinate the response while the facts are still changing.</h2><p className="mt-3 text-sm leading-6 text-slate-600">Keep impact, containment, communications, evidence, and follow-up actions together in a browser-local tester workspace.</p></div><div className="flex flex-wrap gap-2"><Button icon={Plus} variant="primary" onClick={() => setModal("incident")}>New incident</Button><Button icon={Copy} onClick={copySummary}>Copy summary</Button><Button icon={Download} onClick={exportData}>Export</Button></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Stat icon={Flame} label="Severity" value={incident?.severity || "—"} detail={incident?.state || "No incident selected"} /><Stat icon={ClipboardList} label="Action completion" value={`${actionScore}%`} detail={`${doneActions} done of ${actions.length}`} /><Stat icon={AlertCircle} label="Active response" value={activeActions.length} detail={`${criticalImpacts.length} high-impact areas`} /><Stat icon={FileCheck2} label="Evidence" value={evidence.length} detail={`${timeline.length} timeline events`} /></div></div>
    {notice && <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs font-semibold text-emerald-800">{notice}</div>}
    <div className="flex flex-wrap gap-2 border-b border-slate-200 pb-1">{tabs.map(([value, label]) => <button key={value} type="button" onClick={() => setTab(value)} className={`rounded-t-lg px-3 py-2 text-xs font-semibold ${tab === value ? "border-b-2 border-orange-600 text-orange-700" : "text-slate-500"}`}>{label}</button>)}</div>
    <Section title="Incident context" description="Select the active incident or create a new response record." action={<Button icon={RefreshCw} onClick={() => { setData(readData()); setNotice("Incident workspace refreshed"); }}>Refresh</Button>}><div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1fr)_auto]"><label className="text-xs font-semibold text-slate-700">Selected incident<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)} className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm"><option value="">All incidents</option>{data.incidents.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><div className="flex items-end gap-2"><Button icon={ClipboardList} onClick={applyChecklist}>Apply checklist</Button><Button icon={Plus} onClick={() => setModal("incident")}>Add incident</Button></div></div><div className="grid gap-3 border-t border-slate-100 p-5 md:grid-cols-2 xl:grid-cols-3">{data.incidents.map((item) => <button key={item.id} type="button" onClick={() => setSelectedId(item.id)} className={`rounded-xl border p-4 text-left ${selectedId === item.id ? "border-orange-300 bg-orange-50" : "border-slate-200"}`}><div className="flex items-start justify-between gap-3"><p className="text-sm font-semibold">{item.title}</p><Badge value={item.severity}>{item.severity}</Badge></div><p className="mt-2 line-clamp-2 text-xs text-slate-500">{item.summary || "No incident summary recorded."}</p><p className="mt-3 text-[11px] text-slate-400">{item.service || "Service not set"} · {item.lead || "Lead not assigned"}</p></button>)}{!data.incidents.length && <div className="md:col-span-2 xl:col-span-3"><Empty title="No incident response record" description="Create an incident to coordinate triage, containment, and recovery." action={<Button icon={Plus} variant="primary" onClick={() => setModal("incident")}>Create incident</Button>} /></div>}</div></Section>
    {tab === "overview" && <div className="grid gap-5 xl:grid-cols-2"><Section title="Response posture" description="A concise view of what is known and what remains active."><div className="space-y-4 p-5"><div className="rounded-xl border border-orange-100 bg-orange-50 p-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-orange-900">Action progress</p><p className="text-lg font-semibold text-orange-900">{actionScore}%</p></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white"><div className="h-full rounded-full bg-orange-600" style={{ width: `${actionScore}%` }} /></div><p className="mt-3 text-xs text-orange-800">{activeActions.length ? `${activeActions.length} active action${activeActions.length === 1 ? "" : "s"} need follow-up.` : "No active actions recorded."}</p></div><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Communications</p><p className="mt-1 text-xl font-semibold">{communications.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Impact areas</p><p className="mt-1 text-xl font-semibold">{impacts.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Owners</p><p className="mt-1 text-xl font-semibold">{owners.length}</p></div></div><p className="text-[11px] text-slate-500">Response prompt library: {INCIDENT_RESPONSE_NOTES.length} prompts available for triage and handoff.</p></div></Section><Section title="Incident narrative" description="Keep the current understanding visible to every responder."><div className="space-y-4 p-5"><Area label="Summary" value={incident?.summary || ""} onChange={(value) => incident && change("incidents", incident.id, "summary", value)} placeholder="What happened, who is affected, and what is currently known?" /><Area label="Recovery note" value={incident?.recovery || ""} onChange={(value) => incident && change("incidents", incident.id, "recovery", value)} placeholder="What must be true before this incident can be resolved?" /></div></Section><Section title="Response principles" description="Keep the team aligned under pressure."><div className="grid gap-3 p-5 sm:grid-cols-2">{[["Stabilize", "Reduce user harm before optimizing the diagnosis.", ShieldAlert], ["Verify", "Use a reproducible check before declaring recovery.", CheckCircle2], ["Communicate", "Share what is known, unknown, and next.", BellRing], ["Learn", "Turn the incident into prevention work.", ClipboardList]].map(([title, detail, Icon]) => <div key={title} className="rounded-xl border border-slate-200 p-4"><Icon size={17} className="text-orange-600" /><p className="mt-3 text-sm font-semibold">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{detail}</p></div>)}</div></Section><Section title="Recent reports" description="Open a report when it provides direct incident evidence."><div className="divide-y border-t border-slate-100">{reports.slice(0, 5).map((report) => <div key={report.id} className="flex items-center justify-between gap-3 p-4"><div className="min-w-0"><p className="truncate text-sm font-semibold">{report.title || report.summary || `Report ${report.id}`}</p><p className="mt-1 text-[11px] text-slate-500">{report.severity || "Unclassified"} · {report.status || "Open"}</p></div><Button icon={Archive} onClick={() => { onOpenReport?.(report); setNotice("Report opened"); }}>Open</Button></div>)}{!reports.length && <Empty title="No reports available" description="Loaded tester reports will appear here." />}</div></Section></div>}
    {tab === "actions" && <Section title="Containment and recovery actions" description="Make every response action owned, prioritized, and observable." action={<Button icon={Plus} variant="primary" onClick={() => setModal("action")}>Add action</Button>}><div className="flex flex-wrap gap-2 border-b border-slate-100 p-5">{RESPONSE_CHECKLIST.slice(0, 10).map(([title]) => <button key={title} type="button" onClick={() => setActionForm((current) => ({ ...current, title }))} className="rounded-full border border-slate-200 px-3 py-1.5 text-[11px] text-slate-600 hover:border-orange-300 hover:text-orange-700">{title}</button>)}</div>{!actions.length ? <Empty title="No response actions" description="Add an action or apply the response checklist." action={<Button icon={ClipboardList} onClick={applyChecklist}>Apply checklist</Button>} /> : <div className="divide-y">{actions.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.state}>{item.state}</Badge><Badge value={item.priority}>{item.priority}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || `${item.phase || "Response"} action`}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Due: {item.due || "Not set"}</p></div><div className="flex gap-2"><select value={item.state} onChange={(event) => change("actions", item.id, "state", event.target.value)} className="h-8 rounded-lg border border-slate-200 px-2 text-[11px]">{ACTION_STATES.map((state) => <option key={state} value={state}>{state}</option>)}</select><Button variant="danger" icon={Trash2} onClick={() => remove("actions", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    {tab === "timeline" && <Section title="Incident timeline" description="Record observations, hypotheses, changes, and recovery markers." action={<Button icon={Plus} variant="primary" onClick={() => setModal("timeline")}>Add event</Button>}><div className="flex gap-3 border-b border-slate-100 p-5"><div className="relative min-w-0 flex-1"><Search size={15} className="absolute left-3 top-3 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search events, authors, notes..." className="h-10 w-full rounded-lg border border-slate-200 pl-9 pr-3 text-sm" /></div><Button icon={ascending ? ArrowUpAZ : ArrowDownAZ} onClick={() => setAscending((value) => !value)}>Time</Button></div>{!filteredTimeline.length ? <Empty title="No timeline events" description="Add the first observation or incident milestone." action={<Button icon={Plus} onClick={() => setModal("timeline")}>Add event</Button>} /> : <div className="divide-y">{filteredTimeline.map((item) => <div key={item.id} className="flex gap-4 p-5"><div className="mt-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-orange-100 text-orange-700"><Clock3 size={15} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.type}>{item.type}</Badge></div><p className="mt-2 text-xs leading-5 text-slate-600">{item.detail || "No detail recorded."}</p><p className="mt-2 text-[11px] text-slate-500">{item.author || "Unknown author"} · {item.time || item.createdAt}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("timeline", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "impact" && <Section title="Impact assessment" description="Describe who or what is affected and how confident the assessment is." action={<Button icon={Plus} variant="primary" onClick={() => setModal("impact")}>Add impact</Button>}>{!impacts.length ? <Empty title="No impact assessment" description="Record affected journeys, users, services, and confidence." action={<Button icon={Plus} onClick={() => setModal("impact")}>Add impact</Button>} /> : <div className="grid gap-3 p-5 md:grid-cols-2">{impacts.map((item) => <div key={item.id} className="rounded-xl border border-slate-200 p-4"><div className="flex justify-between gap-3"><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.area}</h4><Badge value={item.severity}>{item.severity}</Badge></div><Button variant="danger" icon={Trash2} onClick={() => remove("impacts", item.id)}>Remove</Button></div><p className="mt-3 text-xs text-slate-600">{item.detail || "No detail recorded."}</p><p className="mt-3 text-[11px] text-slate-500">Affected: {item.count || "Unknown"} · Confidence: {item.confidence || "Unknown"}</p></div>)}</div>}</Section>}
    {tab === "communications" && <Section title="Response communications" description="Track internal and external updates without losing the exact wording." action={<Button icon={Plus} variant="primary" onClick={() => setModal("communication")}>Add update</Button>}>{!communications.length ? <Empty title="No communications logged" description="Record status page, chat, email, or stakeholder updates." action={<Button icon={Plus} onClick={() => setModal("communication")}>Add update</Button>} /> : <div className="divide-y">{communications.map((item) => <div key={item.id} className="flex justify-between gap-3 p-5"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.channel}</h4><Badge value={item.status}>{item.status}</Badge></div><p className="mt-2 text-xs leading-5 text-slate-600">{item.message || "No message recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Audience: {item.audience || "Not set"} · Author: {item.author || "Not set"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("communications", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "evidence" && <Section title="Incident evidence" description="Index screenshots, logs, recordings, reports, and recovery proof." action={<Button icon={Plus} variant="primary" onClick={() => setModal("evidence")}>Add evidence</Button>}>{!evidence.length ? <Empty title="No incident evidence" description="Attach proof that supports the diagnosis or recovery claim." action={<Button icon={Plus} onClick={() => setModal("evidence")}>Add evidence</Button>} /> : <div className="divide-y">{evidence.map((item) => <div key={item.id} className="flex justify-between gap-3 p-5"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.kind}>{item.kind}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || "No detail recorded."}</p><p className="mt-2 text-[11px] text-indigo-700">{item.reference || "No reference recorded"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("evidence", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "owners" && <Section title="Response ownership" description="Keep primary and backup responders visible during the incident." action={<Button icon={Plus} variant="primary" onClick={() => setModal("owner")}>Add owner</Button>}>{!owners.length ? <Empty title="No response owners" description="Add the incident lead, technical owner, communications owner, and backups." action={<Button icon={Plus} onClick={() => setModal("owner")}>Add owner</Button>} /> : <div className="grid gap-3 p-5 md:grid-cols-2">{owners.map((item) => <div key={item.id} className="rounded-xl border border-slate-200 p-4"><div className="flex justify-between gap-3"><div><p className="text-sm font-semibold">{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.role} · {item.area}</p></div><Badge value={item.availability}>{item.availability}</Badge></div><p className="mt-3 text-[11px] text-slate-500">Backup: {item.backup || "Not assigned"}</p><div className="mt-3"><Button variant="danger" icon={Trash2} onClick={() => remove("owners", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    {modal === "incident" && <Modal title="Create incident response" onClose={() => setModal("")}><form onSubmit={addIncident} className="space-y-4"><Field label="Incident title" value={incidentForm.title} onChange={(value) => setIncidentForm({ ...incidentForm, title: value })} placeholder="Checkout failures after release" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Severity" options={SEVERITIES} value={incidentForm.severity} onChange={(value) => setIncidentForm({ ...incidentForm, severity: value })} /><Field label="State" options={INCIDENT_STATES} value={incidentForm.state} onChange={(value) => setIncidentForm({ ...incidentForm, state: value })} /><Field label="Incident lead" value={incidentForm.lead} onChange={(value) => setIncidentForm({ ...incidentForm, lead: value })} /><Field label="Service / journey" value={incidentForm.service} onChange={(value) => setIncidentForm({ ...incidentForm, service: value })} /></div><Area label="Summary" value={incidentForm.summary} onChange={(value) => setIncidentForm({ ...incidentForm, summary: value })} placeholder="What happened and what is known now?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Create incident</Button></div></form></Modal>}
    {modal === "action" && <Modal title="Add response action" onClose={() => setModal("")}><form onSubmit={addAction} className="space-y-4"><Field label="Action title" value={actionForm.title} onChange={(value) => setActionForm({ ...actionForm, title: value })} placeholder="Validate rollback in production" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="State" options={ACTION_STATES} value={actionForm.state} onChange={(value) => setActionForm({ ...actionForm, state: value })} /><Field label="Priority" options={SEVERITIES} value={actionForm.priority} onChange={(value) => setActionForm({ ...actionForm, priority: value })} /><Field label="Owner" value={actionForm.owner} onChange={(value) => setActionForm({ ...actionForm, owner: value })} /><Field label="Due" value={actionForm.due} onChange={(value) => setActionForm({ ...actionForm, due: value })} placeholder="Next 30 minutes" /></div><Area label="Detail" value={actionForm.detail} onChange={(value) => setActionForm({ ...actionForm, detail: value })} placeholder="What is the expected result?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add action</Button></div></form></Modal>}
    {modal === "timeline" && <Modal title="Add timeline event" onClose={() => setModal("")}><form onSubmit={addTimeline} className="space-y-4"><Field label="Event title" value={timelineForm.title} onChange={(value) => setTimelineForm({ ...timelineForm, title: value })} placeholder="Error rate returned to baseline" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Event type" options={["Observation", "Hypothesis", "Change", "Decision", "Milestone", "Recovery"]} value={timelineForm.type} onChange={(value) => setTimelineForm({ ...timelineForm, type: value })} /><Field label="Author" value={timelineForm.author} onChange={(value) => setTimelineForm({ ...timelineForm, author: value })} /><Field label="Time" value={timelineForm.time} onChange={(value) => setTimelineForm({ ...timelineForm, time: value })} placeholder="2026-11-13 00:30" /></div><Area label="Detail" value={timelineForm.detail} onChange={(value) => setTimelineForm({ ...timelineForm, detail: value })} placeholder="Record the observation and supporting context." /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add event</Button></div></form></Modal>}
    {modal === "impact" && <Modal title="Add impact assessment" onClose={() => setModal("")}><form onSubmit={addImpact} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Impact area" options={IMPACT_TYPES} value={impactForm.area} onChange={(value) => setImpactForm({ ...impactForm, area: value })} /><Field label="Severity" options={SEVERITIES} value={impactForm.severity} onChange={(value) => setImpactForm({ ...impactForm, severity: value })} /><Field label="Affected count" value={impactForm.count} onChange={(value) => setImpactForm({ ...impactForm, count: value })} placeholder="Approximate or unknown" /><Field label="Confidence" options={["high", "medium", "low"]} value={impactForm.confidence} onChange={(value) => setImpactForm({ ...impactForm, confidence: value })} /></div><Area label="Detail" value={impactForm.detail} onChange={(value) => setImpactForm({ ...impactForm, detail: value })} placeholder="Journeys, users, services, and evidence." /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add impact</Button></div></form></Modal>}
    {modal === "communication" && <Modal title="Add response update" onClose={() => setModal("")}><form onSubmit={addCommunication} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Channel" options={CHANNELS} value={communicationForm.channel} onChange={(value) => setCommunicationForm({ ...communicationForm, channel: value })} /><Field label="Status" options={["draft", "review", "sent", "superseded"]} value={communicationForm.status} onChange={(value) => setCommunicationForm({ ...communicationForm, status: value })} /><Field label="Audience" value={communicationForm.audience} onChange={(value) => setCommunicationForm({ ...communicationForm, audience: value })} placeholder="Customers, support, engineering" /><Field label="Author" value={communicationForm.author} onChange={(value) => setCommunicationForm({ ...communicationForm, author: value })} /></div><Area label="Message" value={communicationForm.message} onChange={(value) => setCommunicationForm({ ...communicationForm, message: value })} placeholder="What is happening, what users should do, and when is the next update?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add update</Button></div></form></Modal>}
    {modal === "evidence" && <Modal title="Add incident evidence" onClose={() => setModal("")}><form onSubmit={addEvidence} className="space-y-4"><Field label="Evidence title" value={evidenceForm.title} onChange={(value) => setEvidenceForm({ ...evidenceForm, title: value })} placeholder="Production error log" required /><Field label="Kind" options={["Screenshot", "Recording", "Log", "Test result", "Report", "Link", "Note"]} value={evidenceForm.kind} onChange={(value) => setEvidenceForm({ ...evidenceForm, kind: value })} /><Field label="Reference" value={evidenceForm.reference} onChange={(value) => setEvidenceForm({ ...evidenceForm, reference: value })} placeholder="URL, report id, or file name" /><Area label="Detail" value={evidenceForm.detail} onChange={(value) => setEvidenceForm({ ...evidenceForm, detail: value })} placeholder="What does this evidence establish?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add evidence</Button></div></form></Modal>}
    {modal === "owner" && <Modal title="Add response owner" onClose={() => setModal("")}><form onSubmit={addOwner} className="space-y-4"><Field label="Name" value={ownerForm.name} onChange={(value) => setOwnerForm({ ...ownerForm, name: value })} placeholder="Primary responder" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Role" value={ownerForm.role} onChange={(value) => setOwnerForm({ ...ownerForm, role: value })} placeholder="Incident lead" /><Field label="Area" value={ownerForm.area} onChange={(value) => setOwnerForm({ ...ownerForm, area: value })} placeholder="Payments" /><Field label="Availability" options={["available", "busy", "offline", "unknown"]} value={ownerForm.availability} onChange={(value) => setOwnerForm({ ...ownerForm, availability: value })} /><Field label="Backup" value={ownerForm.backup} onChange={(value) => setOwnerForm({ ...ownerForm, backup: value })} placeholder="Backup responder" /></div><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add owner</Button></div></form></Modal>}
  </section>;
}
